use crate::aap::caps::{http_client, state_read};

struct Node;

/// Keys under which the 'subscriptions' store may hold the list, tried in order.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Collect the string values (not object keys) of a JSON-shaped text.
fn json_strings(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        loop {
            match chars.next() {
                None | Some('"') => break,
                Some('\\') => match chars.next() {
                    None => break,
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') | Some('f') => {}
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => break,
                            }
                        }
                        if let Some(ch) = char::from_u32(code) {
                            cur.push(ch);
                        }
                    }
                    Some(other) => cur.push(other),
                },
                Some(other) => cur.push(other),
            }
        }
        while matches!(chars.peek(), Some(w) if w.is_whitespace()) {
            chars.next();
        }
        if chars.peek() == Some(&':') {
            // An object key, not a value.
            continue;
        }
        out.push(cur);
    }
    out
}

/// Parse a stored value: a JSON array/object of strings, or plain text with
/// one URL per line (commas and whitespace also separate; `#` starts a comment line).
fn parse_urls(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let candidates: Vec<String> =
        if t.starts_with('[') || t.starts_with('{') || t.starts_with('"') {
            json_strings(t)
        } else {
            t.lines()
                .map(|l| l.trim())
                .filter(|l| !l.starts_with('#'))
                .flat_map(|l| l.split(|c: char| c == ',' || c.is_whitespace()))
                .map(|s| s.to_string())
                .collect()
        };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch requested for every call. RunInfo has no text
        // field, so the run date is used as the query. The result is
        // deliberately unused: the node's output must not change.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&enrich_url);

        let mut urls: Vec<String> = Vec::new();
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

Three things you should know before running this:

- **Enrichment query:** `RunInfo` has no text field, so the enrichment call sends the percent-encoded `date` as `q`. The response is discarded, so the output is unaffected.
- **Instantiation before the release:** the world now imports `aap:caps/http-client@0.1.0`. Until the graph definition is updated, a host that derives imports from the current `with` clause will refuse to instantiate the component. A host outside the handle's allowlist for `metadata.internal.example` will trap on the call.
- **Store key is a guess:** the task does not say which key holds the list, so the node tries `urls`, `subscriptions`, `feeds` and `list` in order. If none yields a URL it returns an empty list, which will fail `present(urls)` rather than invent subscriptions.

